import click
from click.testing import CliRunner

class _PrefixType(click.ParamType):
    name = "prefix"
    def convert(self, value, param, ctx):
        self.fail(f"bad{value}", param, ctx)

def test_raw_value_adjacent_to_word_char_is_not_leaked():
    @click.command()
    def cli():
        click.prompt("Password", hide_input=True, type=_PrefixType())
    result = CliRunner().invoke(cli, input="pass\npass2\n")
    assert "pass" not in result.output.replace("'***'", "")

reviews.raw:
{"decision": "block", "comments": [{"file": "src/click/termui.py", "line_start": 69, "line_end": 71, "body": "Security defect in `_mask_hidden_input`. The raw-value pass uses `(?<!\w)...(?!\w)` lookarounds, so the secret is left unmasked whenever it is directly adjacent to a word character in the message. Example: a custom type that does `self.fail(f"bad{value}", ...)` with value `pass` produces `badpass`, and the lookbehind sees `d`, so nothing is masked and the password is echoed. The same happens for any value that starts or ends with a non-word character (e.g. `-secret` inside `a-secret`, or `!x` inside `q!x`). Before this change, the code fell back to a generic message whenever the value was not cleanly found, so it did not leak in these cases. Masking must not depend on word boundaries when the goal is to hide the input. Mask every occurrence of the raw value (or at least every occurrence that is not a whole-word mismatch of a different token), and do not let surrounding characters decide whether a secret is masked. Also, the new test `test_hide_input_value_never_leaks_when_err_true` passes `mix_stderr=False` to `runner.invoke`. That keyword was removed in Click 8.2, so this test may raise TypeError, and the suite reports 1 failed at the PR head. That failure is not explained by the diff, and the change must not merge with an unexplained failure in its own test file.", "proposed_test": "import click
